targets.rawSql:
select step, ms from (
  select 1 as n, 'Camera starts' as step, percentile_cont(0.5) within group (order by (measures->>'camera_start_to_first_frame_ms')::numeric) as ms
    from telemetry_events where name = 'scan' and $__timeFilter(received_hour) and platform in (${platform:sqlstring})
  union all select 2, 'Code read → payment accepted', percentile_cont(0.5) within group (order by (measures->>'qr_to_admitted_ms')::numeric)
    from telemetry_events where name = 'payment' and $__timeFilter(received_hour) and platform in (${platform:sqlstring})
  union all select 3, 'Wallet prepares', percentile_cont(0.5) within group (order by (measures->>'admitted_to_prepared_ms')::numeric)
    from telemetry_events where name = 'payment' and $__timeFilter(received_hour) and platform in (${platform:sqlstring})
  union all select 4, 'Wallet pays', percentile_cont(0.5) within group (order by (measures->>'submit_to_outcome_ms')::numeric)
    from telemetry_events where name = 'payment' and dimensions->>'outcome' = 'paid' and $__timeFilter(received_hour) and platform in (${platform:sqlstring})
) steps where ms is not null order by n

select date_trunc('day', received_hour) as time, dimensions->>'outcome' as metric, count(*) as value
from telemetry_events where name = 'payment' and $__timeFilter(received_hour) and platform in (${platform:sqlstring})
group by 1, 2 order by 1

select date_trunc('day', received_hour) as time, platform || ' ' || app_version as metric, count(*) as value
from telemetry_events where name = 'launch' and $__timeFilter(received_hour) and platform in (${platform:sqlstring})
group by 1, 2 order by 1
